import { TerminalSquare, Zap, Server, FolderKanban, ShieldCheck, Sparkles, Settings, Network, GitBranch } from "lucide-react";
import { Box } from "@/shared/ui/layout/Box";

// Vendored from `@/app/registry` (unresolvable in this sandbox) — the REAL canonical workspace list,
// unchanged except the GitHub icon: the real app uses `@/shared/ui/icons`' Github wrapper (unresolvable
// here); this sandbox's bundled lucide-react also doesn't export a `Github` brand icon, so `GitBranch`
// stands in as the closest available git-related glyph.
type Workspace = "console" | "glance" | "automation" | "mcp" | "github" | "projects" | "skills" | "security" | "settings";
interface WorkspaceMeta { key: Workspace; label: string; Icon: React.ComponentType<{ size?: number }> }
const WORKSPACES: WorkspaceMeta[] = [
  { key: "console",    label: "Console",     Icon: TerminalSquare },
  { key: "glance",     label: "Glance",      Icon: Network },
  { key: "projects",   label: "Planner",     Icon: FolderKanban },
  { key: "skills",     label: "Skills",      Icon: Sparkles },
  { key: "automation", label: "Automations", Icon: Zap },
  { key: "mcp",        label: "MCP",         Icon: Server },
  { key: "github",     label: "GitHub",      Icon: GitBranch },
  { key: "security",     label: "Security",    Icon: ShieldCheck },
  { key: "settings",   label: "Settings",    Icon: Settings },
];

interface RailProps {
  active?: Workspace;
  onNavigate?: (screen: Workspace) => void;
}
export function Rail({ active = "projects", onNavigate = () => {} }: RailProps) {
  // The legacy Console page is hidden unless opted in (#2372) — this preview always shows it (the
  // real toggle reads `useAppStore().showConsolePage`, app-internal and unresolvable here).
  const destinations = WORKSPACES;
  return (
    <Box className="rail">
      {destinations.map(({ key, Icon, label }) => (
        // eslint-disable-next-line no-restricted-syntax -- bespoke rail nav button (styled by the `.rail button` CSS selector, not the .btn kit)
        <button
          key={key}
          className={key === active ? "active" : ""}
          title={label}
          onClick={() => onNavigate(key)}
        >
          <Icon size={18} />
        </button>
      ))}
    </Box>
  );
}
